}

/* find first index in tsort with target value; returns count or index */
static int tsort_range(uint64_t target, int *lo, int *hi){
    int n = 1<<20;
    *lo = 0; *hi = n;
    /* lower bound */
    int l=0, h=n;
    while(l<h){ int m=(l+h)/2; if((tsort[m]>>20)<target) l=m+1; else h=m; }
    *lo = l;
    h=n;
    while(l<h){ int m=(l+h)/2; if((tsort[m]>>20)<=target) l=m+1; else h=m; }
    *hi = l;
