static inline uint8_t rol2(uint8_t x){ return (uint8_t)((x<<2)|(x>>6)); }
static inline uint8_t ror2(uint8_t x){ return (uint8_t)((x>>2)|(x<<6)); }
static inline uint8_t gf(uint8_t a, uint8_t b, uint8_t x){ return rol2((uint8_t)(a+b+x)); }

static uint32_t F(uint32_t v){
    uint8_t x0=(uint8_t)v, x1=(uint8_t)(v>>8), x2=(uint8_t)(v>>16), x3=(uint8_t)(v>>24);
    uint8_t y2=gf(x3^x2, x1^x0, 1);
    uint8_t y3=gf(x3, y2, 0);
    uint8_t y1=gf(x1^x0, y2, 0);
    uint8_t y0=gf(x0, y1, 1);
    return (uint32_t)y0 | ((uint32_t)y1<<8) | ((uint32_t)y2<<16) | ((uint32_t)y3<<24);
