static uint32_t Finv(uint32_t v){
    uint8_t y0=(uint8_t)v, y1=(uint8_t)(v>>8), y2=(uint8_t)(v>>16), y3=(uint8_t)(v>>24);
    uint8_t x3=(uint8_t)(ror2(y3) - y2);
    uint8_t s01=(uint8_t)(ror2(y1) - y2);
    uint8_t x0=(uint8_t)(ror2(y0) - y1 - 1);
    uint8_t x1=(uint8_t)(x0 ^ s01);
    uint8_t s23=(uint8_t)(ror2(y2) - s01 - 1);
    uint8_t x2=(uint8_t)(s23 ^ x3);
    return (uint32_t)x0 | ((uint32_t)x1<<8) | ((uint32_t)x2<<16) | ((uint32_t)x3<<24);
}

static uint32_t expand(uint32_t k){ return k ^ (k<<16) ^ (k*12345); }

static uint64_t enc(uint32_t l, uint32_t r, const uint32_t K[4]){
    r ^= l;
    for(int i=0;i<4;i++){
        uint32_t m = F(r ^ K[i]);
        uint32_t t = r; r = l ^ m; l = t;
    }
