static uint32_t tgt[1<<20];
static uint32_t d0arr[1<<20];
static uint64_t tsort[1<<20];

static int cmp64(const void *a, const void *b){
    uint64_t x = *(const uint64_t*)a, y = *(const uint64_t*)b;
    return (x>y)-(x<y);
}

static int tsort_range(uint64_t target, int *lo, int *hi){
    int n = 1<<20;
    int l=0, h=n;
    while(l<h){ int m=(l+h)/2; if((tsort[m]>>20)<target) l=m+1; else h=m; }
    *lo = l;
    h=n;
    while(l<h){ int m=(l+h)/2; if((tsort[m]>>20)<=target) l=m+1; else h=m; }
    *hi = l;
