/*
 * Known-plaintext attack on the 4-round FEAL-like cipher in feal.c.
 *
 * Notation (matching feal.c):
 *   plaintext halves:  l = pt>>32, r = pt&0xFFFFFFFF
 *   pre-round:         r ^= l                      (call A = r^l)
 *   round i:           (L', R') = (R, L ^ F(R ^ K[i]))   for i = 0..3
 *   post-round:        L' ^= R'
 *   ciphertext = (R' << 32) | L'
 *
 * From the ciphertext we know:  R4 = ct>>32 and R3 = (ct & 0xFFFFFFFF) ^ R4.
 *
 * Attack:
 *   Guess k3 (20-bit seed) -> K3 = expand(k3)
 *   L3_i = R4_i ^ F(R3_i ^ K3)      (peel round 3; L3_i is really R2_i)
 *   D_i  = F^-1(A_i ^ L3_i)         (= R1_i ^ K1)
 *   E_i  = l_i ^ D_i                (= F(A_i ^ K0) ^ K1)
 *   Tgt  = E_0 ^ E_1                (K1 cancels)
 *
 * With u = A0 ^ K0 and Delta = A0 ^ A1:   F(u) ^ F(u ^ Delta) = Tgt.
 *
 * Precompute Tgt for all 2^20 k3, scan all 2^32 u, and for each hit
 * resolve K0 (must be in the image of expand), K1, K2; verify the full
 * key against all 32 pairs.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/resource.h>

static double now(void){
    struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t);
    return (double)t.tv_sec + (double)t.tv_nsec/1e9;
}
static double cputime(void){
    struct rusage r; getrusage(RUSAGE_SELF,&r);
    return (double)(r.ru_utime.tv_sec + r.ru_stime.tv_sec)
         + (double)(r.ru_utime.tv_usec + r.ru_stime.tv_usec)/1e6;
}

static inline uint8_t rol2(uint8_t x){ return (uint8_t)((x<<2)|(x>>6)); }
static inline uint8_t ror2(uint8_t x){ return (uint8_t)((x>>2)|(x<<6)); }
static inline uint8_t gf(uint8_t a, uint8_t b, uint8_t x){ return rol2((uint8_t)(a+b+x)); }

static uint32_t F(uint32_t v){
    uint8_t x0=(uint8_t)v, x1=(uint8_t)(v>>8), x2=(uint8_t)(v>>16), x3=(uint8_t)(v>>24);
    uint8_t y2=gf(x3^x2, x1^x0, 1);
    uint8_t y3=gf(x3, y2, 0);
    uint8_t y1=gf(x1^x0, y2, 0);
    uint8_t y0=gf(x0, y1, 1);
    return (uint32_t)y0 | ((uint32_t)y1<<8) | ((uint32_t)y2<<16) | ((uint32_t)y3<<24);
}

static uint32_t Finv(uint32_t v){
    uint8_t y0=(uint8_t)v, y1=(uint8_t)(v>>8), y2=(uint8_t)(v>>16), y3=(uint8_t)(v>>24);
    uint8_t x3=(uint8_t)(ror2(y3) - y2);
    uint8_t s01=(uint8_t)(ror2(y1) - y2);
    uint8_t x0=(uint8_t)(ror2(y0) - y1 - 1);
    uint8_t x1=(uint8_t)(x0 ^ s01);
    uint8_t s23=(uint8_t)(ror2(y2) - s01 - 1);
    uint8_t x2=(uint8_t)(s23 ^ x3);
    return (uint32_t)x0 | ((uint32_t)x1<<8) | ((uint32_t)x2<<16) | ((uint32_t)x3<<24);
}

static uint32_t expand(uint32_t k){ return k ^ (k<<16) ^ (k*12345); }

static uint64_t enc(uint32_t l, uint32_t r, const uint32_t K[4]){
    r ^= l;
    for(int i=0;i<4;i++){
        uint32_t m = F(r ^ K[i]);
        uint32_t t = r; r = l ^ m; l = t;
    }
    l ^= r;
    return ((uint64_t)r<<32) | (uint64_t)l;
}

/* ---------- hash set of Tgt values (open addressing) ---------- */
#define SETSIZE (1u<<22)
static uint32_t settab[SETSIZE];
static uint8_t  setbits[SETSIZE/8];
static long setcount=0;

static int set_insert(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        if(!(setbits[i>>3] & (1u<<(i&7)))){
            settab[i]=v; setbits[i>>3] |= (uint8_t)(1u<<(i&7)); setcount++; return 1;
        }
        if(settab[i]==v) return 0;
        i=(i+1)&(SETSIZE-1);
    }
}
static int set_contains(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        if(!(setbits[i>>3] & (1u<<(i&7)))) return 0;
        if(settab[i]==v) return 1;
        i=(i+1)&(SETSIZE-1);
    }
}

/* ---------- map expand(seed) -> seed ---------- */
static uint32_t imaptab[SETSIZE]; /* stores seed+1, 0 = empty */
static int expand_noninjective = 0;

static void ima_insert(uint32_t seed){
    uint32_t v = expand(seed);
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        uint32_t s = imaptab[i];
        if(!s){ imaptab[i]=seed+1; return; }
        if(expand(s-1)==v){ expand_noninjective=1; return; }
        i=(i+1)&(SETSIZE-1);
    }
}
static uint32_t ima_lookup(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        uint32_t s = imaptab[i];
        if(!s) return 0xFFFFFFFFu;
        if(expand(s-1)==v) return s-1;
        i=(i+1)&(SETSIZE-1);
    }
}

#define MAXP 64
static uint32_t L4[MAXP], R4[MAXP];   /* L4[i] actually holds R3_i */
static uint32_t lft[MAXP], rgt[MAXP], A[MAXP];
static uint64_t ct[MAXP];

static uint32_t tgt[1<<20];
static uint32_t d0arr[1<<20];
static uint64_t tsort[1<<20];         /* (tgt << 20) | k3, sorted */

static int cmp64(const void *a, const void *b){
    uint64_t x = *(const uint64_t*)a, y = *(const uint64_t*)b;
    return (x>y)-(x<y);
}

/* target is the 32-bit Tgt value; returns [lo,hi) of entries with that tgt */
static int tsort_range(uint32_t target, int *lo, int *hi){
    int n = 1<<20;
    int l=0, h=n;
    while(l<h){ int m=(l+h)/2; if((uint32_t)(tsort[m]>>20) < target) l=m+1; else h=m; }
    *lo = l;
    h=n;
    while(l<h){ int m=(l+h)/2; if((uint32_t)(tsort[m]>>20) <= target) l=m+1; else h=m; }
    *hi = l;
    return *hi - *lo;
}

int main(int argc, char **argv){
    const char *pairsfile = (argc>1)?argv[1]:"pairs.txt";
    double t0=now();

    for(uint32_t i=0;i<10000;i++){
        uint32_t x = i*0x9E3779B1u ^ 0xA5A5A5A5u;
        if(Finv(F(x))!=x || F(Finv(x))!=x){
            fprintf(stderr,"Finv self-test FAILED\n"); return 2;
        }
    }

    FILE *fp = fopen(pairsfile,"r");
    if(!fp){ fprintf(stderr,"cannot open %s\n",pairsfile); return 2; }
    int NP=0;
    unsigned long p64, c64;
    while(NP<MAXP && fscanf(fp,"%lu %lu",&p64,&c64)==2){
        lft[NP] = (uint32_t)(p64>>32);
        rgt[NP] = (uint32_t)p64;
        A[NP]   = rgt[NP] ^ lft[NP];
        ct[NP]  = (uint64_t)c64;
        R4[NP]  = (uint32_t)(c64>>32);
        L4[NP]  = (uint32_t)c64 ^ R4[NP];   /* = R3 */
        NP++;
    }
    fclose(fp);
    printf("loaded %d pairs\n", NP);
    if(NP<2){ fprintf(stderr,"need at least 2 pairs\n"); return 2; }

    for(uint32_t s=0;s<(1u<<20);s++) ima_insert(s);
    printf("expand non-injective on 20-bit seeds: %s\n",
           expand_noninjective?"yes":"no");

    const uint32_t Delta = A[0]^A[1];
    printf("A0=%08x A1=%08x Delta=%08x\n", A[0], A[1], Delta);

    for(uint32_t k3=0;k3<(1u<<20);k3++){
        uint32_t K3 = expand(k3);
        uint32_t L30 = R4[0] ^ F(L4[0] ^ K3);
        uint32_t L31 = R4[1] ^ F(L4[1] ^ K3);
        uint32_t D0  = Finv(A[0] ^ L30);
        uint32_t D1  = Finv(A[1] ^ L31);
        d0arr[k3] = D0;
        tgt[k3]   = (lft[0]^D0) ^ (lft[1]^D1);
        tsort[k3] = ((uint64_t)tgt[k3]<<20) | (uint64_t)k3;
        set_insert(tgt[k3]);
    }
    qsort(tsort, 1<<20, sizeof(uint64_t), cmp64);
    printf("precompute done: wall=%.2fs cpu=%.2fs distinctTgt=%ld\n",
           now()-t0, cputime(), setcount);

    /* ---- scan all 2^32 u values ---- */
    static uint32_t hits[(1<<22)];
    long nh=0;
    uint64_t iters=0;
    double t1=now(), c1=cuprint_time();
    for(uint32_t u=0;;u++){
        uint32_t e = F(u) ^ F(u ^ Delta);
        if(set_contains(e)){
            if(nh < (1<<22)) hits[nh++] = u;
            else { fprintf(stderr,"hit buffer full\n"); return 3; }
        }
        iters++;
        if((iters & ((uint64_t)1<<26)-1) == 0){
            fprintf(stderr, "  progress: iters=%llu nh=%ld wall=%.1fs cpu=%.1fs\n",
                    (unsigned long long)iters, nh, now()-t1, cputime()-c1);
        }
        if(u==0xFFFFFFFFu) break;
    }
    printf("u-scan done: iters=%llu nh=%ld wall=%.2fs cpu=%.2fs\n",
           (unsigned long long)iters, nh, now()-t1, cputime()-c1);

    /* ---- resolve hits into full keys, verify against all pairs ---- */
    double t2=now();
    long resolved=0;
    for(long i=0;i<nh;i++){
        uint32_t u = hits[i];
        uint32_t e = F(u) ^ F(u ^ Delta);
        uint32_t K0 = u ^ A[0];
        uint32_t k0 = ima_lookup(K0);
        if(k0==0xFFFFFFFFu) continue;
        int lo,hi;
        if(tsort_range(e, &lo, &hi)==0) continue;
        for(int j=lo;j<hi;j++){
            resolved++;
            uint32_t k3 = (uint32_t)(tsort[j] & 0xFFFFF);
            uint32_t K3 = expand(k3);
            uint32_t L30 = R4[0] ^ F(L4[0] ^ K3);
            uint32_t K1 = F(u) ^ lft[0] ^ d0arr[k3];
            uint32_t k1 = ima_lookup(K1);
            if(k1==0xFFFFFFFFu) continue;
            uint32_t K2 = L30 ^ Finv(L4[0] ^ d0arr[k3] ^ K1);
            uint32_t k2 = ima_lookup(K2);
            if(k2==0xFFFFFFFFu) continue;
            uint32_t K[4] = { expand(k0), K1, K2, K3 };
            int ok=1;
            for(int p=0;p<NP;p++)
                if(enc(lft[p], rgt[p], K) != ct[p]){ ok=0; break; }
            if(ok){
                printf("KEY FOUND: seeds = %05x %05x %05x %05x (hex)\n", k0,k1,k2,k3);
                printf("round keys  = %08x %08x %08x %08x\n", K[0],K[1],K[2],K[3]);
                printf("verified against all %d pairs in %.2fs\n", NP, now()-t2);
                return 0;
            }
        }
    }
    printf("NO KEY FOUND: resolved=%ld after wall=%.2fs cpu=%.2fs\n",
           resolved, now()-t0, cputime());
    return 1;
}

