/*
 * Self-check: use the provided ./feal binary to re-encrypt:
 *   (a) every line of plaintexts.txt and compare with ciphertexts.txt
 *   (b) every plaintext in pairs.txt and compare with its ciphertext
 * Also verify ./decrypt inverts ./feal on a few values.
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static const char *KEYS = "68e63 62571 1f61c b74a5";

/* run ./feal <pt_hex> <keys>, return ciphertext parsed from output */
static int feal_enc(uint64_t pt, uint64_t *outct){
    char cmd[256];
    snprintf(cmd, sizeof cmd, "./feal %016llx %s 2>/dev/null",
             (unsigned long long)pt, KEYS);
    FILE *p = popen(cmd, "r");
    if(!p) return 0;
    char line[256]; int got=0;
    while(fgets(line, sizeof line, p)){
        if(strstr(line, "Ciphertext:")){
            unsigned long long v;
            if(sscanf(line+12, "%llx", &v)==1){ *outct=(uint64_t)v; got=1; }
        }
    }
    int rc = pclose(p);
    return got && rc==0;
}

static int check_file(const char *ptfile, const char *ctfile, int expectpairs){
    FILE *fp=fopen(ptfile,"r"), *fc=fopen(ctfile,"r");
    if(!fp||!fc){ fprintf(stderr,"open fail\n"); return 0; }
    unsigned long a,b; int n=0, bad=0;
    while(fscanf(fp,"%lu",&a)==1 && fscanf(fc,"%lu",&b)==1){
        n++;
        uint64_t got;
        if(!feal_enc((uint64_t)a,&got) || got!=(uint64_t)b){
            bad++;
            if(bad<=5) printf("MISMATCH line %d: pt=%lu enc=%llu want=%lu\n",
                               n, a, (unsigned long long)got, b);
        }
    }
    fclose(fp); fclose(fc);
    printf("%s: %d lines, %d mismatches\n", ptfile, n, bad);
    if(expectpairs && n!=expectpairs){ printf("  UNEXPECTED LINE COUNT\n"); bad++; }
    return bad==0;
}

int main(){
    int ok = 1;
    ok &= check_file("plaintexts.txt","ciphertexts.txt",100);
    ok &= check_file("pairs.txt","pairs.txt",32); /* pairs.txt has pt ct pairs */
    /* decrypt binary round-trip check on 5 ciphertexts */
    for(int i=0;i<5;i++){
        FILE *fp=fopen("ciphertexts.txt","r");
        unsigned long ct, pt;
        for(int j=0;j<i;j++) if(fscanf(fp,"%lu",&ct)!=1) break;
        if(fscanf(fp,"%lu",&ct)!=1){ fclose(fp); continue; }
        fclose(fp);
        char cf[64], pf[64], cmd[256];
        snprintf(cf,sizeof cf,"/tmp/vc%d.txt",i);
        snprintf(pf,sizeof pf,"/tmp/vp%d.txt",i);
        FILE *f=fopen(cf,"w"); fprintf(f,"%lu\n",ct); fclose(f);
        snprintf(cmd,sizeof cmd,"./decrypt %s %s > %s 2>/dev/null",cf,KEYS,pf);
        system(cmd);
        FILE *f2=fopen(pf,"r");
        if(fscanf(f2,"%lu",&pt)!=1){ fclose(f2); printf("decrypt fail line %d\n",i); ok=0; continue; }
        fclose(f2);
        /* compare with plaintexts.txt line i */
        FILE *f3=fopen("plaintexts.txt","r");
        unsigned long want;
        for(int j=0;j<i;j++) if(fscanf(f3,"%lu",&want)!=1) break;
        if(fscanf(f3,"%lu",&want)==1 && want!=pt){
            printf("decrypt mismatch line %d: got=%lu want=%lu\n",i,pt,want); ok=0;
        }
        fclose(f3);
        unlink(cf); unlink(pf);
    }
    printf(ok ? "ALL CHECKS PASSED\n" : "CHECKS FAILED\n");
    return ok?0:1;
}

/*
 * Self-check: use the provided ./feal binary to re-encrypt:
 *   (a) every line of plaintexts.txt and compare with ciphertexts.txt
 *   (b) every (plaintext, ciphertext) pair in pairs.txt
 * Also verify ./decrypt inverts on 5 ciphertexts (matching plaintexts.txt).
 */
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static const char *KEYS = "68e63 62571 1f61c b74a5";

/* run ./feal <pt_hex> <keys>, return ciphertext parsed from output */
static int feal_enc(uint64_t pt, uint64_t *outct){
    char cmd[256];
    snprintf(cmd, sizeof cmd, "./feal %016llx %s 2>/dev/null",
             (unsigned long long)pt, KEYS);
    FILE *p = popen(cmd, "r");
    if(!p) return 0;
    char line[256]; int got=0;
    while(fgets(line, sizeof line, p)){
        if(strstr(line, "Ciphertext:")){
            unsigned long long v;
            if(sscanf(line+12, "%llx", &v)==1){ *outct=(uint64_t)v; got=1; }
        }
    }
    int rc = pclose(p);
    return got && rc==0;
}

static int check_files(const char *ptfile, const char *ctfile, int expect_n){
    FILE *fp=fopen(ptfile,"r"), *fc=fopen(ctfile,"r");
    if(!fp||!fc){ fprintf(stderr,"open fail\n"); return 0; }
    unsigned long a,b; int n=0, bad=0;
    while(fscanf(fp,"%lu",&a)==1 && fscanf(fc,"%lu",&b)==1){
        n++;
        uint64_t got;
        if(!feal_enc((uint64_t)a,&got) || got!=(uint64_t)b){
            bad++;
            if(bad<=5) printf("MISMATCH line %d: pt=%lu enc=%llu want=%lu\n",
                               n, a, (unsigned long long)got, b);
        }
    }
    fclose(fp); fclose(fc);
    printf("%s vs %s: %d lines, %d mismatches\n", ptfile, ctfile, n, bad);
    if(expect_n && n!=expect_n){ printf("  UNEXPECTED LINE COUNT (want %d)\n", expect_n); bad++; }
    return bad==0;
}

/* pairs.txt lines: "<plaintext> <ciphertext>" */
static int check_pairs(const char *file){
    FILE *fp=fopen(file,"r");
    if(!fp){ fprintf(stderr,"open fail\n"); return 0; }
    unsigned long a,b; int n=0, bad=0;
    while(fscanf(fp,"%lu %lu",&a,&b)==2){
        n++;
        uint64_t got;
        if(!feal_enc((uint64_t)a,&got) || got!=(uint64_t)b){
