static uint32_t expand(uint32_t k) { return k ^ (k << 16) ^ (k * 12345); }

static uint8_t g(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x) & 0xFF;
    return ((t << 2) | (t >> 6)) & 0xFF;
