static uint32_t F(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g(x[3]^x[2], x[1]^x[0], 1);
    y[3] = g(x[3], y[2], 0);
    y[1] = g(x[1]^x[0], y[2], 0);
    y[0] = g(x[0], y[1], 1);
    uint32_t out = 0;
    for (int i = 0; i < 4; i++) out |= (uint32_t)y[i] << (8*i);
    return out;
}

static uint32_t Finv(uint32_t v) {
    uint8_t y[4];
    for (int i = 0; i < 4; i++) { y[i] = v & 0xFF; v >>= 8; }
    uint32_t out = 0;
