/* ---------- hash set of Tgt values (open addressing) ---------- */
#define SETSIZE (1u<<22)
static uint32_t settab[SETSIZE];
static uint8_t  setbits[SETSIZE/8];

static int set_insert(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        if(!(setbits[i>>3] & (1u<<(i&7)))){
            settab[i]=v; setbits[i>>3] |= (uint8_t)(1u<<(i&7)); return 1;
        }
        if(settab[i]==v) return 0;
        i=(i+1)&(SETSIZE-1);
    }
}
static int set_contains(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        if(!(setbits[i>>3] & (1u<<(i&7)))) return 0;
        if(settab[i]==v) return 1;
        i=(i+1)&(SETSIZE-1);
    }
}

/* ---------- map expand(seed) -> seed (image membership + seed recovery) ---------- */
static uint32_t imaptab[SETSIZE]; /* stores seed+1, 0 = empty */
static int expand_noninjective = 0;

static void ima_insert(uint32_t seed){
    uint32_t v = expand(seed);
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        uint32_t s = imaptab[i];
        if(!s){ imaptab[i]=seed+1; return; }
        if(expand(s-1)==v){ expand_noninjective=1; return; }
        i=(i+1)&(SETSIZE-1);
    }
}
static uint32_t ima_lookup(uint32_t v){
    uint32_t i = (v*0x9E3779B1u) & (SETSIZE-1);
    for(;;){
        uint32_t s = imaptab[i];
        if(!s) return 0xFFFFFFFFu;
        if(expand(s-1)==v) return s-1;
        i=(i+1)&(SETSIZE-1);
    }
}

